import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis', 'Sfax', 'Sousse', 'Monastir', 'Nabeul', 'Bizerte', 'Kairouan', 'Ariana', 'Ben Arous', 'Mahdia'];
const NIVEAUX_STUDENT = ['Primaire', 'Collège', 'Lycée 1ère', 'Lycée 2ème', 'Lycée 3ème (Bac)', 'Université'];

export default function Profile() {
  const { user } = useAuth();
  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', telephone: '',
    niveau: '', tarifs_matieres: [], certificats: [], photo_url: null
  });
  const [structure, setStructure] = useState([]); // Domaines > Niveaux > Matières
  const [loading, setLoading] = useState(true);
  const [saved, setSaved] = useState(false);

  // Modales
  const [showCertModal, setShowCertModal] = useState(false);
  const [newCert, setNewCert] = useState({ titre: '', description: '' });
  const [selectedFile, setSelectedFile] = useState(null);

  useEffect(() => {
    fetchProfileData();
  }, [user]);

  const fetchProfileData = async () => {
    try {
      const isProf = user?.role === 'professeur';
      const route = isProf ? '/api/professeurs/me' : '/api/etudiants/me';
      const res = await api.get(route);
      setForm(res.data);

      if (isProf) {
        const resStruct = await api.get('/api/admin/referentiel/structure');
        setStructure(resStruct.data);
      }
      setLoading(false);
    } catch (e) {
      console.error("Erreur chargement profil", e);
      setLoading(false);
    }
  };

  const handleInput = (key, val) => setForm({ ...form, [key]: val });

  // --- 1. LOGIQUE PHOTO DE PROFIL ---
  const handlePhotoUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const formData = new FormData();
    formData.append('file', file);
    try {
      const res = await api.post('/api/professeurs/me/photo', formData, { 
        headers: { 'Content-Type': 'multipart/form-data' } 
      });
      setForm({ ...form, photo_url: res.data.url });
      alert("✅ Photo de profil mise à jour !");
    } catch (e) { alert("Erreur lors de l'upload de la photo"); }
  };

  // --- 2. LOGIQUE CERTIFICATS ---
  const handleCertUpload = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('titre', newCert.titre);
    formData.append('file', selectedFile);
    try {
      await api.post('/api/professeurs/me/certificats', formData, { 
        headers: { 'Content-Type': 'multipart/form-data' } 
      });
      setShowCertModal(false);
      fetchProfileData();
    } catch (e) { alert("Erreur lors de l'envoi du certificat"); }
  };

  // --- 3. LOGIQUE MATIÈRES & TARIFS ---
  const isSelected = (mId, nId) => form.tarifs_matieres?.some(t => t.matiere_id === mId && t.niveau_id === nId);
  const getTarif = (mId, nId) => form.tarifs_matieres?.find(t => t.matiere_id === mId && t.niveau_id === nId)?.tarif || '';

  const handleToggleMatiere = (matId, nivId) => {
    let list = [...(form.tarifs_matieres || [])];
    if (isSelected(matId, nivId)) {
        list = list.filter(t => !(t.matiere_id === matId && t.niveau_id === nivId));
    } else {
        list.push({ matiere_id: matId, niveau_id: nivId, tarif: 20 });
    }
    setForm({ ...form, tarifs_matieres: list });
  };

  const handlePrice = (mId, nId, p) => {
    const list = form.tarifs_matieres.map(t => 
        (t.matiere_id === mId && t.niveau_id === nId) ? { ...t, tarif: parseFloat(p) || 0 } : t
    );
    setForm({ ...form, tarifs_matieres: list });
  };

  // --- 4. SAUVEGARDE GLOBALE ---
  const handleSave = async () => {
    try {
      const isProf = user?.role === 'professeur';
      const route = isProf ? '/api/professeurs/me' : '/api/etudiants/me';

      const payload = {
        nom: form.user_nom, prenom: form.user_prenom, ville: form.ville,
        telephone: form.telephone, bio: form.bio,
        ...(isProf ? { tarifs_complets: form.tarifs_matieres } : { niveau: form.niveau })
      };

      await api.put(route, payload);
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
      alert("✅ Profil enregistré avec succès !");
    } catch (e) { alert("Erreur lors de la sauvegarde"); }
  };

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '12px', fontSize: '.9rem', width: '100%', outline: 'none', marginBottom: '15px' };

  if (loading) return <div style={{padding:50, textAlign:'center'}}>Chargement du profil...</div>;

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>

      {/* HEADER : PHOTO ET NOM */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 30, marginBottom: 32, background: 'var(--card)', padding: 24, borderRadius: 24, border: '1px solid var(--border)' }}>
        <div style={{ position: 'relative' }}>
          <div style={{ width: 100, height: 100, borderRadius: '50%', overflow: 'hidden', border: '3px solid var(--accent)', background: 'var(--surface2)' }}>
            <img src={form.photo_url ? `http://localhost:8001${form.photo_url}` : 'https://ui-avatars.com/api/?name=' + form.user_prenom} alt="Avatar" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
          </div>
          {user?.role === 'professeur' && (
            <label style={{ position: 'absolute', bottom: 0, right: 0, background: 'var(--accent)', width: 30, height: 30, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', border: '2px solid var(--card)' }}>
              📷 <input type="file" hidden onChange={handlePhotoUpload} />
            </label>
          )}
        </div>
        <div>
          <h2 style={{ fontFamily: 'Syne', fontSize: '1.6rem' }}>{form.user_prenom} {form.user_nom}</h2>
          <p style={{ color: 'var(--text2)', textTransform: 'capitalize' }}>Compte {user?.role}</p>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: user?.role === 'professeur' ? '450px 1fr' : '1fr', gap: 30 }}>

        {/* COLONNE GAUCHE : IDENTITÉ & BIO */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>

          {/* Identité */}
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 20 }}>👤 Informations Personnelles</h3>
            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Prénom</label>
            <input style={inp} value={form.user_prenom || ''} onChange={e => handleInput('user_prenom', e.target.value)} />

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Nom</label>
            <input style={inp} value={form.user_nom || ''} onChange={e => handleInput('user_nom', e.target.value)} />

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Email</label>
            <input style={{...inp, opacity: 0.6}} value={form.email || ''} readOnly />

            {user?.role === 'étudiant' && (
              <>
                <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Mon niveau actuel</label>
                <select style={inp} value={form.niveau} onChange={e => handleInput('niveau', e.target.value)}>
                  <option value="">Sélectionner...</option>
                  {NIVEAUX_STUDENT.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
              </>
            )}

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Téléphone</label>
            <input style={inp} value={form.telephone || ''} placeholder="+216..." onChange={e => handleInput('telephone', e.target.value)} />

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Ville</label>
            <select style={inp} value={form.ville} onChange={e => handleInput('ville', e.target.value)}>
               {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
            </select>

            <button onClick={handleSave} style={{ width:'100%', background:'var(--accent)', color:'#fff', border:'none', padding:14, borderRadius:12, fontWeight:600, cursor:'pointer' }}>
               {saved ? '✅ Enregistré' : 'Sauvegarder le profil'}
            </button>
          </div>

          {/* BIO / DESCRIPTION (Uniquement pour Prof) */}
          {user?.role === 'professeur' && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ marginBottom: 15 }}>📝 Ma Bio / Méthodologie</h3>
              <p style={{ fontSize: '.8rem', color: 'var(--text2)', marginBottom: 10 }}>Présentez-vous aux étudiants en quelques lignes.</p>
              <textarea 
                style={{ ...inp, height: 150, resize: 'none', padding: '15px' }} 
                value={form.bio || ''} 
                placeholder="Ex: Professeur de mathématiques avec 5 ans d'expérience..." 
                onChange={e => handleInput('bio', e.target.value)}
              />
            </div>
          )}

          {/* DIPLOMES (Uniquement pour Prof) */}
          {user?.role === 'professeur' && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
                <h3 style={{ marginBottom: 15 }}>📜 Mes Diplômes</h3>
                <div style={{ display: 'grid', gap: 10, marginBottom: 15 }}>
                    {form.certificats?.map(c => (
                        <div key={c.id} style={{ background: 'var(--surface2)', padding: 12, borderRadius: 12, border: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <span style={{ fontWeight: 600, fontSize: '.85rem' }}>{c.titre}</span>
                            <a href={`http://localhost:8001${c.fichier_url}`} target="_blank" rel="noreferrer" style={{ color: 'var(--accent)' }}>👁️</a>
                        </div>
                    ))}
                </div>
                <button onClick={() => setShowCertModal(true)} style={{ width: '100%', border: '2px dashed var(--border)', background: 'none', color: 'var(--accent)', padding: 15, borderRadius: 12, cursor: 'pointer' }}>+ Ajouter un diplôme</button>
            </div>
          )}
        </div>

        {/* COLONNE DROITE : MATIÈRES & TARIFS (Uniquement pour Prof) */}
        {user?.role === 'professeur' && (
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 20 }}>📚 Mes Enseignements & Tarifs</h3>
            {structure.map(dom => (
              <div key={dom.id} style={{ marginBottom: 35 }}>
                <div style={{ color: 'var(--accent)', fontWeight: 800, fontSize: '1.1rem', marginBottom: 15, borderBottom: '2px solid var(--accent)', paddingBottom: 5 }}>📂 {dom.nom.toUpperCase()}</div>
                {dom.niveaux?.map(niv => (
                  <div key={niv.id} style={{ marginLeft: 15, marginBottom: 25, background: 'var(--surface2)', padding: 20, borderRadius: 20, border: '1px solid var(--border)' }}>
                    <div style={{ fontWeight: 700, fontSize: '1rem', marginBottom: 15 }}>🎓 {niv.nom}</div>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                      {niv.matieres?.map(mat => {
                        const active = isSelected(mat.id, niv.id);
                        return (
                          <div key={mat.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: active ? 'rgba(108,99,255,0.08)' : 'var(--card)', padding: '10px 15px', borderRadius: 12, border: active ? '1px solid var(--accent)' : '1px solid transparent' }}>
                            <label style={{ fontSize: '.85rem', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 10 }}>
                              <input type="checkbox" style={{width:18, height:18}} checked={active} onChange={() => handleToggleMatiere(mat.id, niv.id)} />
                              {mat.nom}
                            </label>
                            {active && (
                              <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                                <input type="number" value={getTarif(mat.id, niv.id)} onChange={e => handlePrice(mat.id, niv.id, e.target.value)} style={{ width: 60, background: 'var(--bg)', color: '#fff', border: '1px solid var(--border)', textAlign: 'center', borderRadius: 8, padding: '4px' }} />
                                <span style={{fontSize:'.7rem', fontWeight:700}}>DT</span>
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            ))}
            <button onClick={handleSave} style={{ width: '100%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', color: '#fff', border: 'none', padding: 18, borderRadius: 15, fontWeight: 700, fontSize: '1rem', cursor: 'pointer' }}>Enregistrer mon catalogue</button>
          </div>
        )}
      </div>

      {/* MODALE DIPLÔME */}
      {showCertModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div style={{ background: 'var(--surface)', padding: 35, borderRadius: 25, width: 450, border: '1px solid var(--border)' }}>
                <h3 style={{marginBottom:20}}>📁 Nouveau Diplôme</h3>
                <form onSubmit={handleCertUpload} style={{ display: 'flex', flexDirection: 'column', gap: 15 }}>
                    <input style={inp} placeholder="Titre (ex: Master en Informatique)" onChange={e => setNewCert({...newCert, titre: e.target.value})} required />
                    <input type="file" style={{color:'white', margin:'10px 0'}} onChange={e => setSelectedFile(e.target.files[0])} required />
                    <div style={{ display: 'flex', gap: 12 }}>
                        <button type="submit" style={{ flex: 2, background: 'var(--accent)', color: '#fff', padding: 12, borderRadius: 12, border: 'none', fontWeight: 700 }}>Sauvegarder</button>
                        <button type="button" onClick={() => setShowCertModal(false)} style={{ flex: 1, background: 'var(--surface2)', color: '#fff', padding: 12, borderRadius: 12, border: 'none' }}>Annuler</button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </div>
  );
}
